 public static object Main(){var root=new GameObject("Feedback router verification");var rigObject=new GameObject("Isolated feedback camera");var camera=rigObject.AddComponent<Camera>();camera.enabled=false;var rig=rigObject.AddComponent<BattleCameraController>();rig.externallyDriven=true;rig.Bind(camera);var a=GameObject.CreatePrimitive(PrimitiveType.Cube);var b=GameObject.CreatePrimitive(PrimitiveType.Cube);a.transform.position=b.transform.position=Vector3.one*1000;var m=new Material(Resources.Load<BattleDioramaSettings>("BattleDioramaSettings").hero);a.GetComponent<Renderer>().sharedMaterial=b.GetComponent<Renderer>().sharedMaterial=m;var profile=new ViewPresentationCoordinator();rig.PrepareTransition(0);profile.Sync(rig);var color=m.GetColor("_BaseColor");int count=0;
  Action<bool,string> check=(ok,name)=>{count++;if(!ok)throw new Exception(name);};
  try{using(var feedback=new CombatFeedbackRouter(root,rig,profile,id=>a.transform)){feedback.SoundEnabled=false;var state=new JObject{{"id","A"},{"fx",new JArray(new JObject{{"id",2},{"kind","damage"},{"target","hero"},{"attackId",88},{"strike",1},{"contactAt",.1f},{"point",new JObject{{"x",0},{"y",100},{"z",5000}}}})}};
   feedback.Update(state,.11f);feedback.Update(state,.12f);check(feedback.ConsumedContacts==1,"event dedup");check(feedback.LastAttackId==88&&feedback.LastStrike==1,"common attack identity");check(Mathf.Abs(feedback.LastContactAt-.1f)<.0001f,"common contact time");var block=new MaterialPropertyBlock();a.GetComponent<Renderer>().GetPropertyBlock(block);check(!block.isEmpty,"target flash applied");b.GetComponent<Renderer>().GetPropertyBlock(block);check(block.isEmpty,"shared material peer untouched");check(m.GetColor("_BaseColor")==color,"source material unchanged");check(rig.ImpactOffset.magnitude<=.08f&&Mathf.Abs(rig.ImpactFov)<=1,"bounded camera offset");
   feedback.Update(state,.7f);a.GetComponent<Renderer>().GetPropertyBlock(block);check(block.isEmpty,"flash restored");check(rig.ImpactOffset==Vector3.zero&&rig.ImpactFov==0,"impact restored");
   state["id"]="B";state["fx"]=new JArray();feedback.Update(state,0);check(rig.ImpactOffset==Vector3.zero,"new session clear");check(root.GetComponentsInChildren<AudioSource>().Length==1,"bounded audio voice");check(root.GetComponentsInChildren<LineRenderer>().Length==9,"fixed trail/spark pool");check(Time.timeScale==1,"global clock unchanged");
  }var result=new JObject{{"passed",true},{"assertions",count},{"audioAudition","not performed; routing/allocation checked"}};File.WriteAllText("C:/Users/SHK/island-view-action-20261107/evidence/feedback-verification.json",result.ToString());return result;
